}

.panel h2 {
  margin: 0 0 1rem;
  font-size: 1.05rem;
}

.field {
  margin-bottom: 0.85rem;
  display: flex;
  flex-direction: column;
}

.field label {
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.muted {
  color: var(--muted);
  font-weight: 400;
}

input,
textarea,
select {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
}

input:focus,
textarea:focus,
select:focus {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
  border-color: var(--primary);
}

textarea {
  resize: vertical;
}

.btn {
  font: inherit;
  padding: 0.5rem 0.9rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  cursor: pointer;
  color: var(--text);
}

.btn:hover {
  background: #f3f4f6;
}

