  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: var(--primary-hover);
}

.btn.link {
  border: none;
  background: none;
  padding: 0.2rem 0.4rem;
  color: var(--primary);
}

.btn.link.danger {
  color: var(--danger);
}

.btn.link:hover {
  text-decoration: underline;
  background: none;
}

.message {
  margin: 0.75rem 0 0;
  padding: 0.5rem 0.7rem;
  border-radius: 8px;
  font-size: 0.9rem;
}

.message.error {
  background: var(--danger-bg);
  color: var(--danger);
}

.message.warn {
  background: #fffbeb;
  color: #92400e;
}

