  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.bookmark {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.85rem 1rem;
}

.bookmark-top {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: baseline;
}

.bookmark-title {
  font-weight: 600;
  color: var(--primary);
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.bookmark-title:hover {
  text-decoration: underline;
}

.bookmark-actions {
  flex-shrink: 0;
  white-space: nowrap;
}

.bookmark-url {
  display: block;
  font-size: 0.8rem;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookmark-note {
  margin: 0.5rem 0 0;
  font-size: 0.9rem;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.bookmark-note.clamped {
  display: -webkit-box;
  -webkit-line-clamp: 3;
