  flex-wrap: wrap;
  gap: 0.35rem;
}

.tag {
  background: var(--tag-bg);
  color: var(--tag-text);
  border-radius: 999px;
  padding: 0.1rem 0.6rem;
  font-size: 0.75rem;
}

.empty {
  color: var(--muted);
