// One-off: seed the review database with sample bookmarks (deletable by the user).
import db from './server/db.js';
import { parseBookmarkUrl } from './server/url.js';

const samples = [
  { url: 'https://developer.mozilla.org/', title: 'MDN Web Docs', tags: ['reference', 'web'], note: 'Go-to docs for HTML, CSS, and JavaScript.' },
  { url: 'https://news.ycombinator.com/', title: 'Hacker News', tags: ['news', 'tech'], note: '' },
  { url: 'https://www.gutenberg.org/', title: 'Project Gutenberg', tags: ['reading', 'books'], note: 'Free public-domain ebooks.' },
  { url: 'https://playwright.dev/', title: 'Playwright', tags: ['testing', 'web'], note: '' },
];

const count = db.prepare('SELECT COUNT(*) c FROM bookmarks').get().c;
if (count > 0) {
  console.log(`DB already has ${count} bookmarks; skipping seed.`);
  process.exit(0);
}

const insert = db.prepare(
  `INSERT INTO bookmarks (url, url_norm, title, note, created_at, updated_at)
   VALUES (@url, @urlNorm, @title, @note, @now, @now)`
